// import positionVert from './shaders/position.vert.wgsl?raw';
// import colorFrag from './shaders/color.frag.wgsl';
import { vec3, mat4 } from 'gl-matrix';

import { Shaders, CreateGPUBufferUint, CreateGPUBuffer } from './shaders/shaders';

import { createTransforms, createViewProjection } from '../Util';

import { CubeData } from './shaders/cube';

const shader = `
// vertex shader

struct Uniforms {
    mvpMatrix : mat4x4<f32>,
};
@binding(0) @group(0) var<uniform> uniforms : Uniforms;

struct Output {
    @builtin(position) Position : vec4<f32>,
    @location(0) vColor : vec4<f32>,
};

@vertex
fn vs_main(@location(0) pos: vec4<f32>, @location(1) color: vec4<f32>) -> Output {
    var output: Output;
    output.Position = uniforms.mvpMatrix * pos;
    output.vColor = color;
    return output;
}

// fragment shader

 @fragment
fn fs_main(@location(0) vColor: vec4<f32>) -> @location(0) vec4<f32> {
    return vColor;
}
`

export class Solution {
    divHost: HTMLElement;
    canvas: HTMLCanvasElement;
    ctx: GPUCanvasContext;
    device: GPUDevice;
    format: GPUTextureFormat;
    size: any;
    pipelineObj: any;
    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        //     console.log(id, 'webGPU', navigator.gpu);
        this.canvas = document.createElement('canvas');
        this.divHost.appendChild(this.canvas);

        this.initWebGPU();
    }
    async initWebGPU() {
        if (!navigator.gpu) { throw new Error('Not Support WebGPU'); }

        const adapter = await navigator.gpu.requestAdapter({
            powerPreference: 'high-performance'
            // powerPreference: 'low-power'
        })

        if (!adapter) { throw new Error('No Adapter Found'); }

        const device = await adapter.requestDevice()
        this.ctx = this.canvas.getContext('webgpu') as GPUCanvasContext
        // @ts-ignore
        const format = navigator.gpu.getPreferredCanvasFormat ? navigator.gpu.getPreferredCanvasFormat() : this.ctx.getPreferredFormat(adapter)
        const devicePixelRatio = window.devicePixelRatio || 1
        this.canvas.width = this.divHost.clientWidth;
        this.canvas.height = this.divHost.clientHeight;
        this.ctx.configure({
            // json specific format when key and value are the same
            device, format,
            // prevent chrome warning
            alphaMode: 'opaque'
        })

        this.size = { width: this.canvas.width, height: this.canvas.height }
        this.device = device;
        this.format = format;


        this.initPipeline(this.device, this.format);
    }
    async initPipeline(device: GPUDevice, format: GPUTextureFormat, primitiveType = 'triangle-list') { // triangle-list , triangle-strip
        // create vertex buffers
        const cubeData = CubeData();
        const numberOfVertices = cubeData.positions.length / 3;
        const vertexBuffer = CreateGPUBuffer(device, cubeData.positions);
        const colorBuffer = CreateGPUBuffer(device, cubeData.colors);

        const pipeline = device.createRenderPipeline({
            layout: 'auto',
            vertex: {
                module: device.createShaderModule({
                    code: shader
                }),
                entryPoint: "vs_main",
                // @ts-ignore
                buffers: [
                    {
                        arrayStride: 12,
                        attributes: [{
                            shaderLocation: 0,
                            format: "float32x3",
                            offset: 0
                        }]
                    },
                    {
                        arrayStride: 12,
                        attributes: [{
                            shaderLocation: 1,
                            format: "float32x3",
                            offset: 0
                        }]
                    }
                ]
            },
            fragment: {
                module: device.createShaderModule({
                    code: shader
                }),
                entryPoint: "fs_main",
                targets: [
                    {
                        format: this.format as GPUTextureFormat
                    }
                ]
            },
            primitive: {
                topology: "triangle-list",
                cullMode: 'back'
            },
            depthStencil: {
                format: "depth24plus",
                depthWriteEnabled: true,
                depthCompare: "less"
            }
        });



        // create uniform data
        const modelMatrix = mat4.create();
        const mvpMatrix = mat4.create();
        let vpMatrix = mat4.create();
        const vp = createViewProjection(this.canvas.width / this.canvas.height);
        vpMatrix = vp.viewProjectionMatrix;

        // create uniform buffer and bind group
        const uniformBuffer = device.createBuffer({
            size: 64,
            usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
        });

        const uniformBindGroup = device.createBindGroup({
            layout: pipeline.getBindGroupLayout(0),
            entries: [
                {
                    binding: 0,
                    resource: {
                        buffer: uniformBuffer,
                        offset: 0,
                        size: 64
                    }
                }
            ]
        });

        const textureView = this.ctx.getCurrentTexture().createView();
        const depthTexture = device.createTexture({
            size: [this.canvas.width, this.canvas.height, 1],
            format: "depth24plus",
            usage: GPUTextureUsage.RENDER_ATTACHMENT
        });
        const renderPassDescription = {
            colorAttachments: [{
                view: textureView,
                clearValue: { r: 0, g: 0, b: 0, a: 1.0 }, //background color
                //loadValue: { r: 0.2, g: 0.247, b: 0.314, a: 1.0  }, 
                loadOp: 'clear',
                storeOp: 'store'
            }],
            depthStencilAttachment: {
                view: depthTexture.createView(),
                depthLoadValue: 1.0,
                depthClearValue: 1.0,
                depthLoadOp: 'clear',
                depthStoreOp: "store",
                /*stencilClearValue: 0,
                stencilLoadValue: 0,
                stencilLoadOp: 'clear',
                stencilStoreOp: "store"*/
            }
        };

        createTransforms(modelMatrix);
        mat4.multiply(mvpMatrix, vpMatrix, modelMatrix);
        device.queue.writeBuffer(uniformBuffer, 0, mvpMatrix as ArrayBuffer);

        const commandEncoder = device.createCommandEncoder();
        const renderPass = commandEncoder.beginRenderPass(renderPassDescription as GPURenderPassDescriptor);
        renderPass.setPipeline(pipeline);
        renderPass.setVertexBuffer(0, vertexBuffer);
        renderPass.setVertexBuffer(1, colorBuffer);
        renderPass.setBindGroup(0, uniformBindGroup);
        renderPass.draw(numberOfVertices);
        renderPass.end();

        device.queue.submit([commandEncoder.finish()]);

    }
    public destroy() {
        this.device.destroy();
        while (this.divHost.lastElementChild) {
            this.divHost.removeChild(this.divHost.lastElementChild);
        }
    }
}